package com.fasterxml.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;

public class TextBufferTest {

    @Test
    public void testGetTextBufferReturnsEmptyArrayAfterResetWithEmpty() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        buffer.resetWithEmpty();

        // First call should return empty array, not null
        char[] result = buffer.getTextBuffer();
        assertNotNull("getTextBuffer should not return null after resetWithEmpty", result);
        assertEquals("getTextBuffer should return empty array after resetWithEmpty", 0, result.length);

        // Second call should also return empty array
        char[] result2 = buffer.getTextBuffer();
        assertNotNull("Second getTextBuffer should not return null", result2);
        assertEquals("Second getTextBuffer should return empty array", 0, result2.length);

        // Verify contentsAsString returns empty string
        assertEquals("contentsAsString should return empty string", "", buffer.contentsAsString());
    }

    @Test
    public void testGetTextBufferReturnsEmptyArrayWhenCurrentSegmentIsNull() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        buffer.resetWithEmpty();

        // Force _currentSegment to be null (simulating empty buffer state)
        // This is the scenario that was causing null to be returned before the fix
        char[] result = buffer.getTextBuffer();
        assertNotNull("getTextBuffer should return empty array even when _currentSegment is null", result);
        assertEquals("Returned array should be empty", 0, result.length);
    }

    @Test
    public void testGetTextBufferConsistency() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        buffer.resetWithEmpty();

        // First call
        char[] firstResult = buffer.getTextBuffer();
        // Call contentsAsString
        String str = buffer.contentsAsString();
        assertEquals("", str);
        // Second call
        char[] secondResult = buffer.getTextBuffer();

        // Both should be non-null empty arrays
        assertNotNull(firstResult);
        assertNotNull(secondResult);
        assertEquals(0, firstResult.length);
        assertEquals(0, secondResult.length);

        // They could be the same array instance or different ones, but both must be empty
        // The important thing is that neither is null
    }

    @Test
    public void testGetTextBufferWithNonEmptyContent() {
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        buffer.append("test", 0, 4);

        char[] result = buffer.getTextBuffer();
        assertNotNull(result);
        assertTrue(result.length >= 4);
        assertEquals('t', result[0]);
        assertEquals('e', result[1]);
        assertEquals('s', result[2]);
        assertEquals('t', result[3]);
    }
}

