package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerAppendTailTest {

    @Test
    public void testAppendTail() {
        // Original issue reproduction
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

        // Expected: "/a2/b/c"
        JsonPointer expected = JsonPointer.compile("/a2/b/c");
        assertEquals(expected.toString(), concatenated.toString());
        assertEquals(expected, concatenated);
    }

    @Test
    public void testAppendTailWithEmptyOriginal() {
        JsonPointer original = JsonPointer.compile("/");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

        // tail of "/" should be "", so appending should yield "/a2"
        JsonPointer expected = JsonPointer.compile("/a2");
        assertEquals(expected.toString(), concatenated.toString());
        assertEquals(expected, concatenated);
    }

    @Test
    public void testAppendTailWithSingleSegment() {
        JsonPointer original = JsonPointer.compile("/a1");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

        // tail of "/a1" should be "", so appending should yield "/a2"
        JsonPointer expected = JsonPointer.compile("/a2");
        assertEquals(expected.toString(), concatenated.toString());
        assertEquals(expected, concatenated);
    }

    @Test
    public void testAppendTailWithMultipleSegments() {
        JsonPointer original = JsonPointer.compile("/a1/b/c/d");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("/x/y");
        JsonPointer concatenated = other.append(tailPointer);

        // Expected: "/x/y/b/c/d"
        JsonPointer expected = JsonPointer.compile("/x/y/b/c/d");
        assertEquals(expected.toString(), concatenated.toString());
        assertEquals(expected, concatenated);
    }

    @Test
    public void testAppendTailWithEmptyOther() {
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("");
        JsonPointer concatenated = other.append(tailPointer);

        // Expected: "/b/c"
        JsonPointer expected = JsonPointer.compile("/b/c");
        assertEquals(expected.toString(), concatenated.toString());
        assertEquals(expected, concatenated);
    }

    @Test
    public void testAppendTailWithSlashEndingOther() {
        // Ensure that trailing slash handling is removed (as per patch comments)
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("/a2/");
        JsonPointer concatenated = other.append(tailPointer);

        // With patch: "/a2//b/c" (double slash because trailing slash is not removed)
        // But note: JsonPointer.compile normalizes multiple slashes? Let's verify.
        JsonPointer expected = JsonPointer.compile("/a2//b/c");
        assertEquals(expected.toString(), concatenated.toString());
        assertEquals(expected, concatenated);
    }

    @Test
    public void testAppendPropertyAndIndexAfterPatch() {
        // Additional tests to ensure other append methods work correctly
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer appendedProperty = ptr.appendProperty("b");
        assertEquals("/a/b", appendedProperty.toString());

        JsonPointer appendedIndex = ptr.appendIndex(0);
        assertEquals("/a/0", appendedIndex.toString());
    }

    @Test
    public void testToStringBuilder() {
        // Test the new toStringBuilder method
        JsonPointer ptr = JsonPointer.compile("/a/b/c");
        StringBuilder sb = ptr.toStringBuilder(10);
        assertEquals("/a/b/c", sb.toString());

        // Test with offset (via tail)
        JsonPointer tail = ptr.tail();
        StringBuilder sb2 = tail.toStringBuilder(5);
        assertEquals("/b/c", sb2.toString());
    }
}

