package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {
    @Test
    public void testEqualsWithNullSnapshotInfo() {
        // Create two versions with null snapshot info
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        // They should be equal
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));
        // Check symmetry
        assertEquals(v1, v2);
        assertEquals(v2, v1);
        // Check hashCode equality
        assertEquals(v1.hashCode(), v2.hashCode());
    }

    @Test
    public void testEqualsWithMixedSnapshotInfo() {
        // One version has null snapshot, the other has non-null
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        // They should NOT be equal
        assertFalse(v1.equals(v2));
        assertFalse(v2.equals(v1));
        // Also test the opposite: non-null vs null
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 2, 3, null, "group", "artifact");
        assertFalse(v3.equals(v4));
        assertFalse(v4.equals(v3));
    }

    @Test
    public void testEqualsWithNonNullSnapshotInfo() {
        // Both have non-null snapshot info
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));
        assertEquals(v1.hashCode(), v2.hashCode());
    }

    @Test
    public void testEqualsWithDifferentSnapshotInfo() {
        // Same version numbers but different snapshot strings
        Version v1 = new Version(1, 2, 3, "ALPHA", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "BETA", "group", "artifact");
        assertFalse(v1.equals(v2));
        assertFalse(v2.equals(v1));
    }

    @Test
    public void testEqualsWithNullSnapshotInfoAndOtherFieldsDifferent() {
        // Different version numbers, same null snapshot
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(2, 3, 4, null, "group", "artifact");
        assertFalse(v1.equals(v2));
        assertFalse(v2.equals(v1));
    }

    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        // Ensure hashCode does not throw NPE when snapshotInfo is null
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        // Just compute hashCode, should not throw
        int hash = v.hashCode();
        // We can't assert a specific value, but we can assert it's consistent with equals
        Version same = new Version(1, 2, 3, null, "group", "artifact");
        assertEquals(v.hashCode(), same.hashCode());
    }

    @Test
    public void testIsSnapshotWithNull() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertFalse(v.isSnapshot());
    }

    @Test
    public void testIsSnapshotWithEmptyString() {
        Version v = new Version(1, 2, 3, "", "group", "artifact");
        assertFalse(v.isSnapshot());
    }

    @Test
    public void testIsSnapshotWithNonEmpty() {
        Version v = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v.isSnapshot());
    }

    @Test
    public void testEqualsReflexive() {
        Version v = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v.equals(v));
    }

    @Test
    public void testEqualsNull() {
        Version v = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v.equals(null));
    }

    @Test
    public void testEqualsDifferentClass() {
        Version v = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v.equals("not a version"));
    }

    @Test
    public void testEqualsSameButDifferentGroup() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group1", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group2", "artifact");
        assertFalse(v1.equals(v2));
    }

    @Test
    public void testEqualsSameButDifferentArtifact() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact1");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact2");
        assertFalse(v1.equals(v2));
    }
}

