package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    // Test equals with null snapshotInfo
    @Test
    public void testEqualsWithNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");

        // Two versions with null snapshotInfo should be equal
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));
        // Should not equal a version with non-null snapshotInfo
        assertFalse(v1.equals(v3));
        assertFalse(v3.equals(v1));
        // Should not equal null
        assertFalse(v1.equals(null));
    }

    // Test equals with non-null snapshotInfo
    @Test
    public void testEqualsWithNonNullSnapshotInfo() {
        Version v1 = new Version(2, 3, 4, "alpha", "com.example", "test");
        Version v2 = new Version(2, 3, 4, "alpha", "com.example", "test");
        Version v3 = new Version(2, 3, 4, "beta", "com.example", "test");
        Version v4 = new Version(2, 3, 4, null, "com.example", "test");

        // Same snapshotInfo should be equal
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));
        // Different snapshotInfo should not be equal
        assertFalse(v1.equals(v3));
        assertFalse(v3.equals(v1));
        // Non-null vs null snapshotInfo should not be equal
        assertFalse(v1.equals(v4));
        assertFalse(v4.equals(v1));
    }

    // Test hashCode with null snapshotInfo (should not throw NPE)
    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        Version v1 = new Version(5, 6, 7, null, "g", "a");
        Version v2 = new Version(5, 6, 7, null, "g", "a");
        // Hash code should be consistent and not throw NPE
        assertEquals(v1.hashCode(), v2.hashCode());
        // Also, hash code of a version with null snapshotInfo should be computable
        // We don't have a specific value to assert, but we can assert it's the same for equal objects
        assertTrue(v1.hashCode() == v2.hashCode());
    }

    // Test hashCode with non-null snapshotInfo
    @Test
    public void testHashCodeWithNonNullSnapshotInfo() {
        Version v1 = new Version(1, 0, 0, "snapshot", "group", "artifact");
        Version v2 = new Version(1, 0, 0, "snapshot", "group", "artifact");
        assertEquals(v1.hashCode(), v2.hashCode());
    }

    // Test isSnapshot method
    @Test
    public void testIsSnapshot() {
        Version vNull = new Version(1, 0, 0, null, "g", "a");
