        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        // Parse field name "a"
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("a", parser.getCurrentName());
        // Parse value 1
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());
        // Parse end object (should not fail due to trailing comma)
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
        parser.close();
    }

    @Test
    public void testTrailingCommaInArrayWithReaderBasedParser() throws IOException {
        // This test is to ensure that trailing comma in array does not break parsing.
        // However, note that nextFieldName is not used for arrays. But the patch also
        // affects array because the same method is called when parsing object within an array?
        // Actually, we should test trailing comma in an array of objects.
        // Let's test a simple array with trailing comma.
        String json = "[1,2,]";
        JsonParser parser = jsonFactory.createParser(json);
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertNull(parser.nextToken());
        parser.close();
    }

