package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import org.junit.Test;
import static org.junit.Assert.*;

import java.io.StringReader;

public class ReaderBasedJsonParserTrailingCommaTest {

    @Test
    public void testNextFieldNameWithTrailingCommaInObject() throws Exception {
        // Test case from issue: trailing comma in object before closing brace
        String json = "{\"enabled\": true,}";
        JsonFactory factory = new JsonFactory();
        factory.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);
        JsonParser parser = factory.createParser(new StringReader(json));

        // Parse first field
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("enabled", parser.nextFieldName());
        assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());

        // Should successfully parse trailing comma and end object
        assertNull(parser.nextFieldName());
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        parser.close();
    }

    @Test
    public void testNextFieldNameWithTrailingCommaInNestedObject() throws Exception {
        // More complex case with nested objects
        String json = "{\"markers\": {\"1\": {\"levelId\": 101,},},}";
        JsonFactory factory = new JsonFactory();
        factory.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);
        JsonParser parser = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("markers", parser.nextFieldName());
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("1", parser.nextFieldName());
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("levelId", parser.nextFieldName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(101, parser.getIntValue());

        // Trailing comma after field in innermost object
        assertNull(parser.nextFieldName());
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        // Trailing comma after field in middle object
        assertNull(parser.nextFieldName());
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        // Trailing comma after field in outermost object
        assertNull(parser.nextFieldName());
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        parser.close();
    }

    @Test
    public void testNextFieldNameWithTrailingCommaInArray() throws Exception {
        // Test trailing comma in array context (though nextFieldName is for objects,
        // we need to ensure array handling doesn't break)
        String json = "{\"topScreens\": [\"Generic_Jungle\", \"ClearBehindBoard_Jungle\",],}";
        JsonFactory factory = new JsonFactory();
        factory.enable(JsonParser.Feature.ALLOW_TRAILING_COMMA);
        JsonParser parser = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("topScreens", parser.nextFieldName());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("Generic_Jungle", parser.getText());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("ClearBehindBoard_Jungle", parser.getText());

        // Array with trailing comma should parse successfully
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());

        // Object with trailing comma should parse successfully
        assertNull(parser.nextFieldName());
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());

        parser.close();
    }

    @Test
    public void testNextFieldNameWithoutTrailingCommaFeature() throws Exception {
        // Without the feature enabled, trailing comma should fail
