package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    @Test
    public void testEqualsWithNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 2, 3, null, "differentGroup", "artifact");
        Version v5 = new Version(1, 2, 3, null, "group", "differentArtifact");

        // Same versions with null snapshotInfo should be equal
        assertEquals(v1, v2);
        // Different snapshotInfo (null vs non-null) should not be equal
        assertNotEquals(v1, v3);
        // Different groupId should not be equal
        assertNotEquals(v1, v4);
        // Different artifactId should not be equal
        assertNotEquals(v1, v5);
        // Test symmetry
        assertEquals(v2, v1);
        // Test with itself
        assertEquals(v1, v1);
        // Test with null
        assertFalse(v1.equals(null));
        // Test with different class
        assertFalse(v1.equals("some string"));
    }

    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        // Equal objects must have equal hash codes
        assertEquals(v1.hashCode(), v2.hashCode());
        // Ensure no exception is thrown
        v1.hashCode();
    }

    @Test
    public void testToStringWithNullSnapshotInfo() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        String s = v.toString();
        // Should be "1.2.3" without any snapshot info
        assertEquals("1.2.3", s);
        // Also test with snapshot info
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertEquals("1.2.3-SNAPSHOT", v2.toString());
    }

    @Test
    public void testIsSnapshotWithNullSnapshotInfo() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertFalse(v.isSnapshot());
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v2.isSnapshot());
        Version v3 = new Version(1, 2, 3, "", "group", "artifact");
        assertFalse(v3.isSnapshot());
    }

    @Test
    public void testEqualsWithNonNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "ALPHA", "group", "artifact");
        assertEquals(v1, v2);
        assertNotEquals(v1, v3);
    }

    @Test
    public void testUnknownVersion() {
        assertTrue(Version.unknownVersion().isUnknownVersion());
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertFalse(v.isUnknownVersion());
    }

    @Test
    public void testToFullString() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertEquals("group/artifact/1.2.3", v.toFullString());
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertEquals("group/artifact/1.2.3-SNAPSHOT", v2.toFullString());
    }
}

