 */
public class VersionTest {

    // Test for issue #1141: NPE in Version.equals() if snapshot-info is null
    @Test
    public void testEqualsWithNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 2, 4, null, "group", "artifact");

        // Two versions with null snapshotInfo should be equal
        assertEquals(v1, v2);
        // v1 should not equal v3 because snapshotInfo differs
        assertNotEquals(v1, v3);
        // v1 should not equal v4 because patchLevel differs
        assertNotEquals(v1, v4);

        // Test symmetry
        assertEquals(v2, v1);
        assertNotEquals(v3, v1);
        assertNotEquals(v4, v1);

        // Test with one null and one non-null snapshotInfo
        assertNotEquals(v1, v3);
        assertNotEquals(v3, v1);
    }

    @Test
    public void testEqualsWithNonNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "ALPHA", "group", "artifact");

        assertEquals(v1, v2);
        assertNotEquals(v1, v3);
    }

    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        // hashCode should not throw NPE and should be equal for equal objects
        assertEquals(v1.hashCode(), v2.hashCode());
        // Just ensure no exception is thrown
        assertDoesNotThrow(() -> v1.hashCode());
    }

    @Test
    public void testHashCodeWithNonNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertEquals(v1.hashCode(), v2.hashCode());
    }

    @Test
    public void testIsSnapshot() {
        Version vNull = new Version(1, 2, 3, null, "group", "artifact");
        Version vEmpty = new Version(1, 2, 3, "", "group", "artifact");
        Version vSnapshot = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");

        assertFalse(vNull.isSnapshot());
        assertFalse(vEmpty.isSnapshot());
        assertTrue(vSnapshot.isSnapshot());
    }

    @Test
    public void testEqualsReflexive() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertEquals(v, v);
    }

