package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.filter.TokenFilter;
import com.fasterxml.jackson.core.filter.FilteringGeneratorDelegate;
import com.fasterxml.jackson.core.util.JsonGeneratorDelegate;
import java.io.IOException;
import java.io.StringWriter;
import java.util.Set;
import java.util.HashSet;
import java.util.List;
import java.util.ArrayList;
import java.util.function.UnaryOperator;
import java.util.stream.Collectors;

import org.junit.Test;
import static org.junit.Assert.*;

public class FilteringGeneratorDelegateTest {

    // Helper class from the issue description
    private static final class OrTokenFilter extends TokenFilter {
        private final List<? extends TokenFilter> delegates;

        private OrTokenFilter(final List<? extends TokenFilter> delegates) {
            this.delegates = delegates;
        }

        static OrTokenFilter create(final Set<String> jsonPointers) {
            return new OrTokenFilter(jsonPointers.stream().map(JsonPointerBasedFilter::new).collect(Collectors.toList()));
        }

        @Override
        public TokenFilter includeElement(final int index) {
            return executeDelegates(delegate -> delegate.includeElement(index));
        }

        @Override
        public TokenFilter includeProperty(final String name) {
            return executeDelegates(delegate -> delegate.includeProperty(name));
        }

        @Override
        public TokenFilter filterStartArray() {
            return this;
        }

        @Override
        public TokenFilter filterStartObject() {
            return this;
        }

        private TokenFilter executeDelegates(final UnaryOperator<TokenFilter> operator) {
            List<TokenFilter> nextDelegates = null;
            for (final TokenFilter delegate : delegates) {
                final TokenFilter next = operator.apply(delegate);
                if (null == next) {
                    continue;
                }
                if (TokenFilter.INCLUDE_ALL == next) {
                    return TokenFilter.INCLUDE_ALL;
                }

                if (null == nextDelegates) {
                    nextDelegates = new ArrayList<>(delegates.size());
                }
                nextDelegates.add(next);
            }
            return null == nextDelegates ? null : new OrTokenFilter(nextDelegates);
        }
    }

    @Test
    public void testWriteStartObjectCreatesChildContextWhenFilterIsNull() throws IOException {
        // Setup: create a composite filter that matches multiple paths
        Set<String> jsonPointers = new HashSet<>();
        jsonPointers.add("/id");
        jsonPointers.add("/stuff/0/name");

        OrTokenFilter compositeFilter = OrTokenFilter.create(jsonPointers);

        // Create a generator with the composite filter
        StringWriter sw = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator generator = factory.createGenerator(sw);

        FilteringGeneratorDelegate filteringGenerator = new FilteringGeneratorDelegate(
            generator, 
            compositeFilter, 
            TokenFilter.Inclusion.INCLUDE_ALL_AND_PATH, 
            true
        );

        // Write JSON structure similar to the issue example
        filteringGenerator.writeStartArray(); // root array

        // First object
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("id", "1");

        filteringGenerator.writeFieldName("stuff");
        filteringGenerator.writeStartArray();

        // First object in stuff array - should match "/stuff/0/name"
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("name", "name1");
        filteringGenerator.writeEndObject();

        // Second object in stuff array - should NOT match any filter
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("name", "name2");
        filteringGenerator.writeEndObject();

        filteringGenerator.writeEndArray(); // end stuff array
        filteringGenerator.writeEndObject(); // end first object

        // Second object (this is where the bug would manifest without the fix)
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("id", "2");

        filteringGenerator.writeFieldName("stuff");
        filteringGenerator.writeStartArray();

        // First object in second stuff array - should match "/stuff/0/name"
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("name", "name1");
        filteringGenerator.writeEndObject();

        // Second object in second stuff array - should NOT match any filter
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("name", "name2");
        filteringGenerator.writeEndObject();

        filteringGenerator.writeEndArray(); // end second stuff array
        filteringGenerator.writeEndObject(); // end second object

        filteringGenerator.writeEndArray(); // end root array
        filteringGenerator.close();

        // Verify the output contains the filtered content
        String result = sw.toString();
        assertNotNull(result);
        // The exact output depends on the filtering logic, but the main point is
        // that the generation should complete without throwing an exception
        // due to incorrect filter context state
    }

    @Test
    public void testWriteStartObjectWithNullFilterCreatesChildContext() throws IOException {
        // Test with a filter that returns null for objects
        TokenFilter nullFilter = new TokenFilter() {
            @Override
            public TokenFilter filterStartObject() {
                return null;
            }

            @Override
            public TokenFilter filterStartArray() {
                return TokenFilter.INCLUDE_ALL;
            }
        };

        StringWriter sw = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator generator = factory.createGenerator(sw);

        FilteringGeneratorDelegate filteringGenerator = new FilteringGeneratorDelegate(
            generator, 
            nullFilter, 
            TokenFilter.Inclusion.INCLUDE_ALL_AND_PATH, 
            true
        );

        // Write an object that should be filtered out
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("field", "value");
        filteringGenerator.writeEndObject();

        // Write an array that should be included
        filteringGenerator.writeStartArray();
        filteringGenerator.writeNumber(1);
        filteringGenerator.writeEndArray();

        filteringGenerator.close();

        // The object should be filtered out, but the array should be included
        String result = sw.toString();
        // The exact output depends on the inclusion mode, but the key is that
        // no exception should be thrown due to missing filter context
        assertNotNull(result);
    }

    @Test
    public void testMultipleWriteStartObjectCallsWithCompositeFilter() throws IOException {
        // This test specifically exercises the scenario from the issue
        Set<String> jsonPointers = new HashSet<>();
        jsonPointers.add("/a");
        jsonPointers.add("/b/0/c");

        OrTokenFilter compositeFilter = OrTokenFilter.create(jsonPointers);

        StringWriter sw = new StringWriter();
        JsonFactory factory = new JsonFactory();
        JsonGenerator generator = factory.createGenerator(sw);

        FilteringGeneratorDelegate filteringGenerator = new FilteringGeneratorDelegate(
            generator, 
            compositeFilter, 
            TokenFilter.Inclusion.INCLUDE_ALL_AND_PATH, 
            true
        );

        // Write structure that triggers the bug: nested objects where some are filtered
        filteringGenerator.writeStartArray();

        // First object with property "a"
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("a", "value1");
        filteringGenerator.writeEndObject();

        // Second object with nested array
        filteringGenerator.writeStartObject();
        filteringGenerator.writeFieldName("b");
        filteringGenerator.writeStartArray();

        // First object in array with property "c"
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("c", "value2");
        filteringGenerator.writeEndObject();

        // Second object in array without matching property
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("d", "value3");
        filteringGenerator.writeEndObject();

        filteringGenerator.writeEndArray();
        filteringGenerator.writeEndObject();

        // Third object (similar to second) - this would fail without the fix
        filteringGenerator.writeStartObject();
        filteringGenerator.writeFieldName("b");
        filteringGenerator.writeStartArray();

        // First object in array with property "c"
        filteringGenerator.writeStartObject();
        filteringGenerator.writeStringField("c", "value4");
        filteringGenerator.writeEndObject();

        filteringGenerator.writeEndArray();
        filteringGenerator.writeEndObject();

        filteringGenerator.writeEndArray();
        filteringGenerator.close();

        // The test passes if no exception is thrown
        assertNotNull(sw.toString());
    }
}

