import java.nio.ByteBuffer;

import static org.junit.Assert.*;

public class JsonFactoryCanonicalizeFieldNamesTest {

    // Helper method to test canonicalization for a given parser
    private void testCanonicalization(JsonParser parser, boolean expectCanonicalize) throws IOException {
        // Parse an object with two identical field names
        // JSON: {"field":"value1","field":"value2"}
        // Actually, we cannot have duplicate fields in JSON object, but we can parse sequentially.
        // We'll parse a stream of tokens: START_OBJECT, FIELD_NAME, VALUE_STRING, FIELD_NAME, VALUE_STRING, END_OBJECT
        // We'll collect the field name strings and compare references.
        String fieldName1 = null;
        String fieldName2 = null;

        while (parser.nextToken() != null) {
            if (parser.currentToken() == JsonToken.FIELD_NAME) {
                if (fieldName1 == null) {
                    fieldName1 = parser.getCurrentName();
                } else {
                    fieldName2 = parser.getCurrentName();
                    break; // we have both, no need to continue
                }
            }
        }
        parser.close();

        assertNotNull(fieldName1);
        assertNotNull(fieldName2);
        assertEquals("field", fieldName1);
        assertEquals("field", fieldName2);

        if (expectCanonicalize) {
            // When canonicalization is enabled, the same String instance should be returned.
            assertSame("Field names should be the same String instance when canonicalization is enabled",
                    fieldName1, fieldName2);
        } else {
            // When canonicalization is disabled, they may be different instances (though they could be interned by JVM).
            // We cannot guarantee they are different because of JVM string interning, but the canonicalizer should not enforce it.
            // However, with the patch, the symbol table is not canonicalizing, so they should be different instances.
            // But note: if the same string literal is used, they might be the same due to JVM interning.
            // We are parsing from bytes, so they are not string literals. So we can assert they are not the same.
            assertNotSame("Field names should not be the same String instance when canonicalization is disabled",
                    fieldName1, fieldName2);
        }
    }

