package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Test;

import java.io.IOException;
import java.io.StringReader;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

public class Base64PaddingReadTest {

    // Test case for issue #912: when padding is allowed, missing padding should not throw exception.
    @Test
    public void testBase64WithoutPaddingWhenPaddingAllowed() throws IOException {
        // Create a Base64 variant that allows missing padding on read.
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = new JsonFactory();

        // Base64 string for "test" without padding: "dGVzdA" (standard "dGVzdA==" with padding)
        String json = "{\"data\":\"dGVzdA\"}";
        JsonParser parser = factory.createParser(json);

        // Advance to start object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        // Field name
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("data", parser.getCurrentName());
        // Value token
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        byte[] decoded = parser.getBinaryValue(variant);

        // Expected bytes for "test"
        byte[] expected = new byte[] { 't', 'e', 's', 't' };
        assertArrayEquals(expected, decoded);
        parser.close();
    }

    // Additional test: when padding is required, missing padding should throw exception.
    @Test
    public void testBase64WithoutPaddingWhenPaddingRequired() throws IOException {
        // Use the default MIME_NO_LINEFEEDS which requires padding on read (by default).
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;
        // Ensure it requires padding (default behavior)
        assert variant.requiresPaddingOnRead();
        JsonFactory factory = new JsonFactory();

        String json = "{\"data\":\"dGVzdA\"}";
        JsonParser parser = factory.createParser(json);

        // Advance to start object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        // Field name
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("data", parser.getCurrentName());
        // Value token
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        try {
            parser.getBinaryValue(variant);
            fail("Expected IOException due to missing padding");
        } catch (IOException e) {
            // Expected: should throw an exception about missing padding
            // We can optionally check the message, but not necessary.
        } finally {
            parser.close();
        }
    }

    // Test with a longer Base64 string without padding (multiple chunks).
    @Test
    public void testLongerBase64WithoutPaddingWhenPaddingAllowed() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = new JsonFactory();

        // Base64 for "hello world!" without padding: "aGVsbG8gd29ybGQh"
        String json = "{\"data\":\"aGVsbG8gd29ybGQh\"}";
        JsonParser parser = factory.createParser(json);

        // Advance to start object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        // Field name
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("data", parser.getCurrentName());
        // Value token
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        byte[] decoded = parser.getBinaryValue(variant);

        byte[] expected = "hello world!".getBytes("UTF-8");
        assertArrayEquals(expected, decoded);
        parser.close();
    }

    // Test using JsonParser directly (to cover the specific parser classes).
    @Test
    public void testDirectParserWithPaddingAllowed() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = new JsonFactory();
        String json = "\"dGVzdA\"";
        JsonParser parser = factory.createParser(new StringReader(json));
        // Advance to the value
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        byte[] decoded = parser.getBinaryValue(variant);
        byte[] expected = new byte[] { 't', 'e', 's', 't' };
        assertArrayEquals(expected, decoded);
        parser.close();
    }

    // Test the exact example from the issue (with the long base64 string).
    @Test
    public void testIssueExample() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = new JsonFactory();
        String json = "{\"diff\":\"\"}";

        JsonParser parser = factory.createParser(json);
        // Advance to start object
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        // Field name
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("diff", parser.getCurrentName());
        // Value token
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        // We don't need to check the actual bytes, just that no exception is thrown.
        byte[] decoded = parser.getBinaryValue(variant);
        assertNotNull(decoded);
        // The base64 string is long, so we just assert it's not empty.
        assert decoded.length > 0;
        parser.close();
    }

    // Helper method to avoid static import conflict
    private static void assertEquals(JsonToken expected, JsonToken actual) {
        org.junit.Assert.assertEquals(expected, actual);
    }

    private static void assertEquals(String expected, String actual) {
        org.junit.Assert.assertEquals(expected, actual);
    }
}

