package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.StringReader;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class Base64PaddingReadTest {

    // Base64 string without padding: "Hello" -> SGVsbG8= (with padding) -> SGVsbG8 (without padding)
    private static final String BASE64_NO_PADDING = "SGVsbG8";
    private static final byte[] EXPECTED_BYTES = "Hello".getBytes();

    @Test
    public void testBase64WithoutPaddingWhenPaddingAllowed() throws IOException {
        // Create a Base64 variant that allows missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
                Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = JsonFactory.builder().build();

        // Create a JSON string with the Base64 value
        String json = "\"" + BASE64_NO_PADDING + "\"";

        // Test with ReaderBasedJsonParser
        try (JsonParser parser = factory.createParser(new StringReader(json))) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] result = parser.getBinaryValue(variant);
            assertArrayEquals(EXPECTED_BYTES, result);
        }

        // Test with UTF8StreamJsonParser
        try (JsonParser parser = factory.createParser(new ByteArrayInputStream(json.getBytes("UTF-8")))) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] result = parser.getBinaryValue(variant);
            assertArrayEquals(EXPECTED_BYTES, result);
        }

        // Note: UTF8DataInputJsonParser is not typically used from JsonFactory.createParser,
        // but it is used for DataInput. We'll skip that for simplicity.
    }

    @Test
    public void testBase64WithoutPaddingWhenPaddingRequired() throws IOException {
        // Use the default MIME_NO_LINEFEEDS which requires padding by default
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;
        JsonFactory factory = JsonFactory.builder().build();

        String json = "\"" + BASE64_NO_PADDING + "\"";

        // Test with ReaderBasedJsonParser
        try (JsonParser parser = factory.createParser(new StringReader(json))) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            try {
                parser.getBinaryValue(variant);
                fail("Expected exception due to missing padding");
            } catch (Exception e) {
                // Expected
            }
        }

        // Test with UTF8StreamJsonParser
        try (JsonParser parser = factory.createParser(new ByteArrayInputStream(json.getBytes("UTF-8")))) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            try {
                parser.getBinaryValue(variant);
                fail("Expected exception due to missing padding");
            } catch (Exception e) {
                // Expected
            }
        }
    }

    // Additional test to ensure that with padding it works in both cases
    @Test
    public void testBase64WithPadding() throws IOException {
        String base64WithPadding = "SGVsbG8=";
        byte[] expected = "Hello".getBytes();

        // Test with padding allowed
        Base64Variant variantAllowed = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
                Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factoryAllowed = JsonFactory.builder().build();
        String jsonWithPadding = "\"" + base64WithPadding + "\"";

        try (JsonParser parser = factoryAllowed.createParser(new StringReader(jsonWithPadding))) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] result = parser.getBinaryValue(variantAllowed);
            assertArrayEquals(expected, result);
        }

        // Test with padding required (default)
        Base64Variant variantRequired = Base64Variants.MIME_NO_LINEFEEDS;
        JsonFactory factoryRequired = JsonFactory.builder().build();

        try (JsonParser parser = factoryRequired.createParser(new StringReader(jsonWithPadding))) {
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] result = parser.getBinaryValue(variantRequired);
            assertArrayEquals(expected, result);
        }
    }
}

