            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            // For non-numeric tokens, getNumberTypeFP should return UNKNOWN
            assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
