package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.Base64Variants;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import org.junit.Test;

import java.util.Base64;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class Base64PaddingReadTest {

    // Test for issue #912: Base64 without padding when padding is allowed.
    @Test
    public void testBase64MissingPaddingWhenAllowed() throws Exception {
        // Create a variant that allows missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = new JsonFactory();

        // Test with different byte array lengths to cover both 2-bit and 4-bit missing padding.
        int[] lengths = {1, 2, 4, 5};
        for (int len : lengths) {
            // Generate random bytes
            byte[] original = new byte[len];
            for (int i = 0; i < len; i++) {
                original[i] = (byte) (i + 65);
            }
            // Encode without padding using Java's Base64 encoder
            String base64WithoutPadding = Base64.getEncoder().withoutPadding().encodeToString(original);
            // Create JSON string
            String json = "{\"diff\":\"" + base64WithoutPadding + "\"}";

            // Parse with JsonParser
            try (JsonParser parser = factory.createParser(json)) {
                assertEquals(JsonToken.START_OBJECT, parser.nextToken());
                assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
                assertEquals("diff", parser.getCurrentName());
                assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
                byte[] parsed = parser.getBinaryValue(variant);
                assertArrayEquals("Failed for length " + len, original, parsed);
                assertEquals(JsonToken.END_OBJECT, parser.nextToken());
            }
        }
    }

    // Test that when padding is required, missing padding throws an exception.
    @Test(expected = com.fasterxml.jackson.core.JsonParseException.class)
    public void testBase64MissingPaddingWhenRequired() throws Exception {
        // Use variant that requires padding (default)
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS; // uses PADDING_REQUIRED by default
        JsonFactory factory = new JsonFactory();

        // Use a byte array of length 5 -> Base64 without padding is 7 characters (missing one padding)
        byte[] original = new byte[5];
        for (int i = 0; i < 5; i++) {
            original[i] = (byte) (i + 65);
        }
        String base64WithoutPadding = Base64.getEncoder().withoutPadding().encodeToString(original);
        String json = "{\"diff\":\"" + base64WithoutPadding + "\"}";

        try (JsonParser parser = factory.createParser(json)) {
            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
            assertEquals("diff", parser.getCurrentName());
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            // This should throw JsonParseException due to missing padding
            parser.getBinaryValue(variant);
        }
    }

    // Test that when padding is present, parsing works regardless of the setting.
    @Test
    public void testBase64WithPadding() throws Exception {
        // Test with padding allowed and required: both should work when padding is present.
        Base64Variant[] variants = {
            Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED),
            Base64Variants.MIME_NO_LINEFEEDS // required
        };

        for (Base64Variant variant : variants) {
            JsonFactory factory = new JsonFactory();
            byte[] original = new byte[5];
            for (int i = 0; i < 5; i++) {
                original[i] = (byte) (i + 65);
            }
            // Encode with padding
            String base64WithPadding = Base64.getEncoder().encodeToString(original);
            String json = "{\"diff\":\"" + base64WithPadding + "\"}";

            try (JsonParser parser = factory.createParser(json)) {
                assertEquals(JsonToken.START_OBJECT, parser.nextToken());
                assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
                assertEquals("diff", parser.getCurrentName());
                assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
                byte[] parsed = parser.getBinaryValue(variant);
                assertArrayEquals(original, parsed);
                assertEquals(JsonToken.END_OBJECT, parser.nextToken());
            }
        }
    }

    // Additional test from the first version: specific case with "MTIzNDU" (7 chars, missing one padding)
    @Test
    public void testBase64WithoutPaddingWhenPaddingAllowedSpecific() throws Exception {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);
        JsonFactory factory = new JsonFactory();
        String json = "{\"diff\":\"MTIzNDU\"}"; // "MTIzNDU" is 7 characters, missing one padding.

        try (JsonParser parser = factory.createParser(json)) {
            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
            assertEquals("diff", parser.getCurrentName());
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            byte[] parsed = parser.getBinaryValue(variant);
            byte[] expected = new byte[]{49, 50, 51, 52, 53}; // ASCII for '1','2','3','4','5'
            assertArrayEquals(expected, parsed);
            assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        }
    }

    @Test(expected = com.fasterxml.jackson.core.JsonParseException.class)
    public void testBase64WithoutPaddingWhenPaddingRequiredSpecific() throws Exception {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS; // default requires padding
        JsonFactory factory = new JsonFactory();
        String json = "{\"diff\":\"MTIzNDU\"}"; // missing padding

        try (JsonParser parser = factory.createParser(json)) {
            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
            assertEquals("diff", parser.getCurrentName());
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
            // This should throw JsonParseException due to missing padding
            parser.getBinaryValue(variant);
        }
    }
}

