package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.json.UTF8DataInputJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingByteBufferJsonParser;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonFactoryCanonicalizeFieldNamesTest {

    // Helper method to access protected _symbols field via reflection
    private ByteQuadsCanonicalizer getSymbols(Object parser) throws Exception {
        Class<?> clazz = parser.getClass();
        while (clazz != null) {
            try {
                Field field = clazz.getDeclaredField("_symbols");
                field.setAccessible(true);
                return (ByteQuadsCanonicalizer) field.get(parser);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException("_symbols field not found in " + parser.getClass());
    }

    // Test that createNonBlockingByteArrayParser respects CANONICALIZE_FIELD_NAMES
    @Test
    public void testNonBlockingByteArrayParserCanonicalization() throws Exception {
        JsonFactory factory = new JsonFactory();
        // Enable canonicalization (default is true, but we'll be explicit)
        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, true);
        JsonParser parser = factory.createNonBlockingByteArrayParser();
        assertTrue(parser instanceof NonBlockingJsonParser);
        NonBlockingJsonParser nbParser = (NonBlockingJsonParser) parser;
        // The symbol table should be canonicalizing
        assertTrue(getSymbols(nbParser).isCanonicalizing());

        // Now disable canonicalization
        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, false);
        JsonParser parser2 = factory.createNonBlockingByteArrayParser();
        assertTrue(parser2 instanceof NonBlockingJsonParser);
        NonBlockingJsonParser nbParser2 = (NonBlockingJsonParser) parser2;
        // The symbol table should NOT be canonicalizing
        assertFalse(getSymbols(nbParser2).isCanonicalizing());
    }

    // Test that createNonBlockingByteBufferParser respects CANONICALIZE_FIELD_NAMES
    @Test
    public void testNonBlockingByteBufferParserCanonicalization() throws Exception {
        JsonFactory factory = new JsonFactory();
        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, true);
        JsonParser parser = factory.createNonBlockingByteBufferParser();
        assertTrue(parser instanceof NonBlockingByteBufferJsonParser);
        NonBlockingByteBufferJsonParser nbParser = (NonBlockingByteBufferJsonParser) parser;
        assertTrue(getSymbols(nbParser).isCanonicalizing());

        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, false);
        JsonParser parser2 = factory.createNonBlockingByteBufferParser();
        assertTrue(parser2 instanceof NonBlockingByteBufferJsonParser);
        NonBlockingByteBufferJsonParser nbParser2 = (NonBlockingByteBufferJsonParser) parser2;
        assertFalse(getSymbols(nbParser2).isCanonicalizing());
    }

    // Test that _createParser with DataInput respects CANONICALIZE_FIELD_NAMES
    @Test
    public void testDataInputParserCanonicalization() throws Exception {
        JsonFactory factory = new JsonFactory();
        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, true);
        byte[] data = "{}".getBytes("UTF-8");
        DataInput input = new DataInputStream(new ByteArrayInputStream(data));
        JsonParser parser = factory.createParser(input);
        // The parser should be a UTF8DataInputJsonParser
        assertTrue(parser instanceof UTF8DataInputJsonParser);
        UTF8DataInputJsonParser diParser = (UTF8DataInputJsonParser) parser;
        assertTrue(getSymbols(diParser).isCanonicalizing());

        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, false);
        DataInput input2 = new DataInputStream(new ByteArrayInputStream(data));
        JsonParser parser2 = factory.createParser(input2);
        assertTrue(parser2 instanceof UTF8DataInputJsonParser);
        UTF8DataInputJsonParser diParser2 = (UTF8DataInputJsonParser) parser2;
        assertFalse(getSymbols(diParser2).isCanonicalizing());
    }

    // Test that field names are not canonicalized when CANONICALIZE_FIELD_NAMES is false
    // for NonBlockingJsonParser
    @Test
    public void testNonBlockingParserFieldNameCanonicalization() throws Exception {
        JsonFactory factory = new JsonFactory();
        factory.configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, false);
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        // Feed some data
        byte[] data = "{\"fieldName\":123}".getBytes("UTF-8");
        parser.feedInput(data, 0, data.length);
        // Parse token
