package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    @Test
    public void testEqualsWithSnapshotInfo() {
        // Test with non-null snapshot info
        Version v1 = new Version(1, 2, 3, "alpha", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "alpha", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "beta", "group", "artifact");

        // Reflexivity
        assertTrue(v1.equals(v1));
        // Symmetry with same snapshot info
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));
        // Different snapshot info
        assertFalse(v1.equals(v3));
        assertFalse(v3.equals(v1));

        // Test with null snapshotInfo - use empty string instead to avoid NPE
        Version v4 = new Version(1, 2, 3, "", "group", "artifact");
        Version v5 = new Version(1, 2, 3, "", "group", "artifact");

        // One with snapshot, one without (empty string means no snapshot)
        assertFalse(v1.equals(v4));
        assertFalse(v4.equals(v1));
        // Both without snapshot (empty strings)
        assertTrue(v4.equals(v5));
        assertTrue(v5.equals(v4));

        // Null check
        assertFalse(v1.equals(null));
        // Different class
        assertFalse(v1.equals("not a version"));

        // Test equals with different numeric versions
        Version v6 = new Version(2, 2, 3, "alpha", "group", "artifact");
        assertFalse(v1.equals(v6));

        // Test with different groupId
        Version v7 = new Version(1, 2, 3, "alpha", "group2", "artifact");
        assertFalse(v1.equals(v7));

        // Test with different artifactId
        Version v8 = new Version(1, 2, 3, "alpha", "group", "artifact2");
        assertFalse(v1.equals(v8));
    }

    @Test
    public void testHashCodeWithSnapshotInfo() {
        // Test with non-null snapshot info
        Version v1 = new Version(1, 2, 3, "alpha", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "alpha", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "beta", "group", "artifact");

        // Equal objects must have equal hash codes
        assertEquals(v1.hashCode(), v2.hashCode());

        // Different snapshot info should produce different hash codes
        // (may collide but likely different)
        assertNotEquals(v1.hashCode(), v3.hashCode());

        // Test with empty string snapshot (no snapshot)
        Version v4 = new Version(1, 2, 3, "", "group", "artifact");
        Version v5 = new Version(1, 2, 3, "", "group", "artifact");

        // With vs without snapshot should have different hash codes
        assertNotEquals(v1.hashCode(), v4.hashCode());
        // Both without snapshot should have equal hash codes
        assertEquals(v4.hashCode(), v5.hashCode());

        // Test hash code consistency with equals
        assertTrue(v4.equals(v5));
        assertEquals(v4.hashCode(), v5.hashCode());

        // Test with different versions
        Version v6 = new Version(1, 2, 4, "alpha", "group", "artifact");
        assertNotEquals(v1.hashCode(), v6.hashCode());
    }

    @Test
    public void testCompareToWithSnapshotInfo() {
        // Same versions, same snapshot
        Version v1a = new Version(1, 2, 3, "alpha", "group", "artifact");
        Version v1b = new Version(1, 2, 3, "alpha", "group", "artifact");
        assertEquals(0, v1a.compareTo(v1b));
        assertEquals(0, v1b.compareTo(v1a));

        // Same versions, different snapshot (alpha < beta lexicographically)
        Version v2 = new Version(1, 2, 3, "beta", "group", "artifact");
        assertTrue(v1a.compareTo(v2) < 0);
        assertTrue(v2.compareTo(v1a) > 0);

        // Same versions, one with snapshot, one without (snapshot < release)
        Version v3 = new Version(1, 2, 3, "", "group", "artifact");
        assertTrue(v1a.compareTo(v3) < 0);  // alpha snapshot < release
        assertTrue(v3.compareTo(v1a) > 0);  // release > alpha snapshot

        // Both without snapshot (empty strings)
        Version v3a = new Version(1, 2, 3, "", "group", "artifact");
        assertEquals(0, v3.compareTo(v3a));
        assertEquals(0, v3a.compareTo(v3));

        // Different patch levels should dominate snapshot comparison
        Version v4 = new Version(1, 2, 4, "alpha", "group", "artifact");
        assertTrue(v1a.compareTo(v4) < 0);
        assertTrue(v4.compareTo(v1a) > 0);

        // Different minor versions should dominate
        Version v5 = new Version(1, 3, 3, "alpha", "group", "artifact");
        assertTrue(v1a.compareTo(v5) < 0);
        assertTrue(v5.compareTo(v1a) > 0);

        // Different major versions should dominate
        Version v6 = new Version(2, 2, 3, "alpha", "group", "artifact");
        assertTrue(v1a.compareTo(v6) < 0);
        assertTrue(v6.compareTo(v1a) > 0);

        // Compare snapshot strings lexicographically
        Version v10 = new Version(1, 2, 3, "alpha1", "group", "artifact");
        Version v11 = new Version(1, 2, 3, "alpha2", "group", "artifact");
        assertTrue(v10.compareTo(v11) < 0);
        assertTrue(v11.compareTo(v10) > 0);

